from pathlib import Path
import subprocess, xml.etree.ElementTree as ET
p=Path(__file__).parent
items=[
('01-smile','会心一笑','SMILE / FRIENDLY','#167C66','#E9F3EE','把笑弧放进对话气泡，让 问候与对话 合成一个符号。温和、直接，适合作为主品牌。','<path d="M50 18C30 18 16 30 16 47c0 11 6 20 16 25l-3 12 18-7h3c20 0 34-12 34-30S70 18 50 18Z" fill="none" stroke="currentColor" stroke-width="6" stroke-linejoin="round"/><path d="M34 48q16 22 32 0" fill="none" stroke="currentColor" stroke-width="6" stroke-linecap="round"/>'),
('02-refine','妙笔生花','REFINE / INTELLIGENT','#6852B0','#F0ECF8','圆润笔尖与一颗星光，表达文字被轻轻润色。功能指向明确，呼应现有菜单栏的魔法棒。','<path d="M24 75 32 45 56 21 78 43 54 67Z" fill="currentColor"/><path d="m26 73 25-25" stroke="#F0ECF8" stroke-width="5" stroke-linecap="round"/><path d="M78 57q0 14 13 14-13 0-13 14 0-14-13-14 13 0 13-14Z" fill="currentColor"/>'),
('03-h-bridge','言语之桥','BRIDGE / DISTINCTIVE','#2961A0','#EAF0F8','以两条圆角竖柱和微笑曲线构成 H：既是 Hola 的首字母，也像连接两个人的桥。','<path d="M26 24v52m48-52v52M26 47q24 22 48 0" fill="none" stroke="currentColor" stroke-width="12" stroke-linecap="round"/>'),
('04-flow','顺畅表达','FLOW / CALM','#B76532','#FAF0E5','三条由短到长的文字线，收束成向上的柔和曲线。强调把生硬句子变得自然、顺畅。','<g fill="none" stroke="currentColor" stroke-width="7" stroke-linecap="round"><path d="M22 28h32"/><path d="M22 47h47"/><path d="M22 66h29q20 0 28-14"/></g>'),
('05-quote','对话有温度','QUOTE / HUMAN','#AF4E61','#F9EBEF','两个相向的引号形成交流关系，厚实的圆形轮廓带来亲和感。更偏人文、沟通与陪伴。','<g fill="currentColor"><path d="M43 24C27 24 17 36 17 51v18h27V44H29c1-7 6-11 14-12Z"/><path d="M57 76c16 0 26-12 26-27V31H56v25h15c-1 7-6 11-14 12Z"/></g>')]
# The nib uses a true transparent cutout, so every logo remains monochrome.
items[1]=(*items[1][:6], '<defs><mask id="nib"><rect width="100" height="100" fill="white"/><path d="m26 73 25-25" stroke="black" stroke-width="5" stroke-linecap="round"/></mask></defs><path d="M24 75 32 45 56 21 78 43 54 67Z" fill="currentColor" mask="url(#nib)"/><path d="M78 57q0 14 13 14-13 0-13 14 0-14-13-14 13 0 13-14Z" fill="currentColor"/>')
def svg(body,color=None):
    return f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"'+(f' color="{color}"' if color else '')+'>'+body+'</svg>'
cards=[]
board=['<svg xmlns="http://www.w3.org/2000/svg" width="1600" height="850" viewBox="0 0 1600 850"><rect width="1600" height="850" fill="#F8F7F4"/><g font-family="Helvetica, Arial, sans-serif" fill="#242B29"><text x="64" y="87" font-size="46" font-weight="600">Hola</text><text x="66" y="126" font-size="17" fill="#6B726E">让每句话，更好地被理解。 /  五个品牌方向</text><text x="1530" y="86" text-anchor="end" font-size="13" letter-spacing="2">LOGO EXPLORATION — 2026</text>']
for i,(slug,name,sub,col,bg,desc,body) in enumerate(items):
    (p/(slug+'.svg')).write_text(svg(body))
    (p/(slug+'-color.svg')).write_text(svg(body,col))
    subprocess.run(['rsvg-convert','-w','1024','-h','1024','-o',str(p/(slug+'.png')),str(p/(slug+'-color.svg'))],check=True)
    icon=svg(body)
    cards.append(f'<article style="--accent:{col};--tint:{bg}"><div class="art">{icon}</div><div class="info"><small>0{i+1} / {sub}</small><h2>{name}</h2><p>{desc}</p><div class="samples"><span style="width:16px">{icon}</span><span style="width:24px">{icon}</span><span style="width:40px">{icon}</span><span class="inverse">{icon}</span></div><div class="links"><a href="{slug}.svg" download>SVG</a><a href="{slug}.png" download>PNG</a><button onclick="choose(this,{i+1})">选择这个方向</button></div></div></article>')
    x=64+i*300
    board.append(f'<rect x="{x}" y="197" width="276" height="300" rx="22" fill="{bg}"/><svg x="{x+48}" y="246" width="180" height="180" viewBox="0 0 100 100" color="{col}">{body}</svg><text x="{x}" y="541" font-size="13" fill="#6B726E">0{i+1} / {sub.split(" / ")[0]}</text><text x="{x}" y="580" font-size="25" font-weight="600">{name}</text><svg x="{x}" y="620" width="24" height="24" viewBox="0 0 100 100" color="#242B29">{body.replace("nib","nibsmall")}</svg><svg x="{x+48}" y="612" width="40" height="40" viewBox="0 0 100 100" color="#242B29">{body.replace("nib","nibmedium")}</svg><rect x="{x+119}" y="601" width="60" height="60" rx="14" fill="#242B29"/><svg x="{x+129}" y="611" width="40" height="40" viewBox="0 0 100 100" color="white">{body.replace("nib","nibwhite")}</svg>')
board.append('<path d="M64 724H1536" stroke="#DDDFDA"/><text x="64" y="776" font-size="16" fill="#6B726E">macOS 文字润色助手 · 彩色主标 / 单色缩略 / 深色适配</text><text x="1536" y="776" text-anchor="end" font-size="15" fill="#6B726E">推荐 01：友好直观    /    03：品牌辨识</text></g></svg>')
(p/'overview.svg').write_text(''.join(board))
subprocess.run(['rsvg-convert','-o',str(p/'overview.png'),str(p/'overview.svg')],check=True)
html='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Hola · Logo 方案</title><style>
*{box-sizing:border-box}body{margin:0;background:#f8f7f4;color:#242b29;font-family:-apple-system,BlinkMacSystemFont,sans-serif}main{max-width:1440px;margin:auto;padding:64px 32px}header{display:flex;justify-content:space-between;gap:28px;align-items:end;margin-bottom:48px}h1{font-size:54px;letter-spacing:-2px;margin:0 0 14px}header p{color:#68716d;font-size:18px;margin:0}button,a{font:inherit}button{cursor:pointer;border:1px solid #c8cdc7;border-radius:20px;padding:9px 15px;background:transparent;color:inherit}button:focus-visible,a:focus-visible{outline:3px solid #268775;outline-offset:4px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:28px}article{border:1px solid #e0e2dc;border-radius:24px;overflow:hidden;background:#fff;transition:transform .2s}article:hover{transform:translateY(-3px)}article.selected{outline:3px solid var(--accent)}.art{height:250px;background:var(--tint);color:var(--accent);display:grid;place-items:center}.art svg{width:160px;height:160px}.info{padding:26px}small{font-size:10px;letter-spacing:1.5px;color:#777}h2{font-size:24px;margin:12px 0}p{line-height:1.8;font-size:14px;color:#68716d;min-height:76px}.samples{display:flex;align-items:center;gap:22px;height:66px;color:#242b29}.samples span{display:inline-flex}.inverse{width:48px;padding:4px;background:#242b29;color:white;border-radius:12px}.links{border-top:1px solid #e8e9e4;margin-top:20px;padding-top:18px;display:flex;align-items:center;gap:16px}a{font-size:12px;color:inherit;text-decoration:none}.links button{margin-left:auto;font-size:12px}footer{margin-top:40px;color:#68716d;font-size:13px}.mono .art{color:#242b29;background:#eeefeb}.dark .art{color:#fff;background:#242b29}@media(max-width:1050px){.grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:640px){main{padding:32px 20px}.grid{grid-template-columns:1fr}header{display:block}header button{margin-top:20px}h1{font-size:42px}}@media(prefers-reduced-motion:reduce){article{transition:none}}
</style><main><header><div><h1>Hola</h1><p>让每句话，更好地被理解。</p></div><button id="mode" onclick="cycle()">外观：品牌色</button></header><div class="grid">'''+''.join(cards)+'''</div><footer><p id="selection" aria-live="polite">点击选中喜欢的方向，再在聊天里告诉我编号。推荐 01「会心一笑」或 03「言语之桥」。</p>SVG 为透明底单色矢量；PNG 为 1024 × 1024 透明底品牌色。页面可离线使用。</footer></main><script>let mode=0;function cycle(){mode=(mode+1)%3;document.body.className=['','mono','dark'][mode];document.getElementById('mode').textContent='外观：'+['品牌色','单色','深色'][mode]}function choose(b,n){document.querySelectorAll('article').forEach(a=>a.classList.remove('selected'));b.closest('article').classList.add('selected');document.getElementById('selection').textContent='已选方向 0'+n+'。请在聊天里告诉我编号和希望调整的细节。'}</script></html>'''
(p/'index.html').write_text(html)
(p/'README.md').write_text('# Hola Logo 探索\n\n根据 Sources/main.swift 的当前实现，产品是 macOS 菜单栏文字润色助手，重点是保持原意、改善语气与流畅度。仓库主 README 仍描述早期 AX 测试工具，设计以源码为依据。\n\n使用 logo-generator Skill 的几何 / 线条 / 字母抽象设计流程，按用户要求交付五款。展示页沿用 Skill 的卡片比较方式，改为无外部依赖的离线页面。\n\n'+ '\n\n'.join(f'## {i+1}. {n}\n\n{d}\n\n主色：{c}。文件：`{s}.svg`、`{s}-color.svg`、`{s}.png`。' for i,(s,n,_,c,_,d,_) in enumerate(items))+'\n\n打开 index.html 比较品牌色、单色和深色，以及 16 / 24 / 40 px 缩略。小尺寸为浏览器预览，尚未集成 macOS 状态栏实测。图案为可编辑 SVG，PNG 由 rsvg-convert 渲染。此阶段未调用生成式图像服务；选定方向后再制作应用图标或展示图。\n')
for f in p.glob('*.svg'): ET.parse(f)
print('Generated 5 concepts, 5 PNGs, SVG originals, overview and interactive HTML; all SVG XML valid.')
